using System;
using System.Collections;
using System.Collections.Generic;
using System.Threading;
using Cysharp.Threading.Tasks;
using MiniFramework.Contracts;
using MiniFramework.Runtime;
using MiniFramework.Pool;
using MiniFramework.Bindings;
using MiniFramework.Providers.Fake;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.TestTools;
using Object=UnityEngine.Object;
namespace MiniFramework.Maintenance.Tests
{
    public sealed class ResourceMaintenanceTests
    {
        private static CleanupContext Cleanup=>new CleanupContext(default,Timeout.InfiniteTimeSpan);
        private static ResourceKey SpriteKey(string key)=>new ResourceKey("fake","main","v1",key,typeof(Sprite));
        private static ResourceKey PrefabKey(string key="prefab")=>new ResourceKey("fake","main","v1",key,typeof(GameObject));
        private readonly List<Env> environments=new List<Env>();
        private async UniTask<Env> New(int perFrame=1){var e=new Env(perFrame);environments.Add(e);await e.Init();return e;}
        private sealed class Provider:IAssetProvider
        {
            internal readonly FakeResourceProvider Fake=new FakeResourceProvider();internal bool AutoLoads=true,AutoReleases=true;
            internal GameObject Prefab;internal Sprite Sprite;private readonly List<Action> pumps=new List<Action>();
            public string Id=>Fake.Id;
            public Result<IProviderOperation<IProviderAsset<T>>> BeginLoad<T>(ResourceKey key)where T:class
            {
                var result=Fake.BeginLoad<T>(key);var load=Fake.AssetAt<T>(Fake.AssetStartCount-1);
                pumps.Add(()=>{if(AutoLoads&&load.Operation.State==BackendState.Running)load.Succeed((T)(object)(typeof(T)==typeof(Sprite)?(Object)Sprite:Prefab));if(AutoReleases)load.Asset?.ReleaseAttempt?.Complete(Result<Unit>.Success(default));});return result;
            }
            internal void Step(){foreach(var pump in pumps)pump();}
        }
        private sealed class Target:IResourceTarget<Sprite>
        {internal bool Alive=true,ThrowSet;internal Action OnSet;private Sprite value;public bool IsAlive=>Alive;public Sprite Value{get=>value;set{this.value=value;OnSet?.Invoke();if(ThrowSet)throw new Exception("setter");}}}
        private sealed class Env
        {
            internal readonly Provider Provider=new Provider();internal readonly Scope Owner=new Scope("owner");
            internal readonly ResourceWorkScheduler Scheduler=new ResourceWorkScheduler(new ResourceScheduleBudget(4,4,4,TimeSpan.FromSeconds(1)));
            internal readonly AssetsService Assets;internal readonly GameObjectPool Pool;internal readonly ManualMemoryPressureSource Source=new ManualMemoryPressureSource();
            internal readonly MemoryPressureController Pressure;internal GameContext Context;
            internal readonly List<Object> Objects=new List<Object>();internal readonly List<Target> Targets=new List<Target>();
            internal readonly Sprite A,B;internal readonly Texture2D Texture;
            internal Env(int perFrame)
            {
                Texture=new Texture2D(2,2);A=Sprite.Create(Texture,new Rect(0,0,1,1),Vector2.zero);B=Sprite.Create(Texture,new Rect(1,0,1,1),Vector2.zero);
                Objects.Add(A);Objects.Add(B);Objects.Add(Texture);Provider.Sprite=A;
                Provider.Prefab=new GameObject("maintenance-template");Provider.Prefab.SetActive(false);Objects.Add(Provider.Prefab);
                var child=new GameObject("Icon",typeof(RectTransform),typeof(CanvasRenderer),typeof(Image));child.transform.SetParent(Provider.Prefab.transform,false);
                Assets=new AssetsService(Provider,"main","v1",Cleanup,scheduler:Scheduler,schedulerModuleId:Scheduler.Id);
                Pool=new GameObjectPool(Assets,Scheduler,new PoolCapacity(8,8),Cleanup);
                Pressure=new MemoryPressureController(Source,Scheduler,Pool,perFrame,Cleanup);
            }
            internal async UniTask Init()
            {
                Context=new GameContext(new[]{new ModuleRegistration(Scheduler.Id,Scheduler.Dependencies,()=>Scheduler,typeof(IResourceWorkScheduler)),
                    new ModuleRegistration(Assets.Id,Assets.Dependencies,()=>Assets,typeof(IAssetsService)),
                    new ModuleRegistration(Pool.Id,Pool.Dependencies,()=>Pool,typeof(IPoolService<GameObject>)),
                    new ModuleRegistration(Pressure.Id,Pressure.Dependencies,()=>Pressure,typeof(IMemoryPressureHandler))},Cleanup);
                Assert.IsTrue((await Context.StartAsync(OperationContext.Unlimited())).IsSuccess);
            }
            internal void Step(){Scheduler.Tick();Pool.PollDestroyed();Provider.Step();}
            internal async UniTask<T> Pump<T>(UniTask<T> task){for(var i=0;task.Status==UniTaskStatus.Pending&&i<600;i++){Step();await UniTask.Yield();}Assert.AreNotEqual(UniTaskStatus.Pending,task.Status,"did not drain");return await task;}
            internal AssetBinding<Sprite> Binding(out Target target){target=new Target();Targets.Add(target);return AssetBinding<Sprite>.Create("binding/"+Targets.Count,Assets,target,Owner,Cleanup).Value;}
            internal async UniTask<IPoolRent<GameObject>> Rent(string key="prefab"){var result=await Pump(Pool.Spawn(PrefabKey(key),Owner).Value.WaitAsync(OperationContext.Unlimited()));Assert.IsTrue(result.IsSuccess);return result.Value;}
            internal async UniTask Finish()
            {
                Provider.AutoLoads=Provider.AutoReleases=true;foreach(var t in Targets){t.ThrowSet=false;t.OnSet=null;}
                var closed=await Pump(Owner.CloseAsync(Cleanup));if(!closed.IsFullyDrained)await Pump(Owner.RetryFailedAsync(Cleanup));
                var result=await Pump(Context.CloseAsync(OperationContext.Unlimited()));if(!result.IsSuccess)result=await Pump(Context.CloseAsync(OperationContext.Unlimited()));
                Assert.IsTrue(result.IsSuccess);Assert.AreEqual(0,Assets.RetainedEntryCount);Assert.AreEqual(0,Pool.BucketCount);Assert.AreEqual(0,Source.SubscriberCount);
                foreach(var obj in Objects)if(obj!=null)Object.DestroyImmediate(obj);
            }
        }
        [UnityTearDown] public IEnumerator TearDown()=>UniTask.ToCoroutine(async()=>{foreach(var e in environments)await e.Finish();environments.Clear();});
        [UnityTest] public IEnumerator LateAAfterBDoesNotOverwriteLatest()=>UniTask.ToCoroutine(async()=>{var e=await New();e.Provider.AutoLoads=false;var binding=e.Binding(out var target);var a=binding.SetAsync(SpriteKey("a"),OperationContext.Unlimited());e.Step();var b=binding.SetAsync(SpriteKey("b"),OperationContext.Unlimited());e.Step();e.Provider.Fake.AssetAt<Sprite>(1).Succeed(e.B);Assert.IsTrue((await e.Pump(b)).IsSuccess);e.Provider.Fake.AssetAt<Sprite>(0).Succeed(e.A);Assert.AreEqual(ErrorKind.Canceled,(await e.Pump(a)).Error.Kind);for(var i=0;i<4;i++){e.Step();await UniTask.Yield();}Assert.AreSame(e.B,target.Value);Assert.AreEqual(AssetLeaseState.Released,e.Provider.Fake.AssetAt<Sprite>(0).Asset.State);});
        [UnityTest] public IEnumerator FailedReplacementKeepsPreviousVisibleLease()=>UniTask.ToCoroutine(async()=>{var e=await New();var binding=e.Binding(out var target);await e.Pump(binding.SetAsync(SpriteKey("a"),OperationContext.Unlimited()));e.Provider.AutoLoads=false;var b=binding.SetAsync(SpriteKey("b"),OperationContext.Unlimited());e.Step();e.Provider.Fake.AssetAt<Sprite>(1).Fail(new FrameworkError(ErrorKind.Provider,"missing"));Assert.IsFalse((await e.Pump(b)).IsSuccess);Assert.AreSame(e.A,target.Value);Assert.AreEqual(AssetLeaseState.Active,e.Provider.Fake.AssetAt<Sprite>(0).Asset.State);});
        [UnityTest] public IEnumerator SwapCommitsBeforePreviousReleaseCompletes()=>UniTask.ToCoroutine(async()=>{var e=await New();var binding=e.Binding(out var target);await e.Pump(binding.SetAsync(SpriteKey("a"),OperationContext.Unlimited()));e.Provider.AutoReleases=false;e.Provider.Sprite=e.B;Assert.IsTrue((await e.Pump(binding.SetAsync(SpriteKey("b"),OperationContext.Unlimited()))).IsSuccess);Assert.AreSame(e.B,target.Value);Assert.AreEqual(AssetLeaseState.Releasing,e.Provider.Fake.AssetAt<Sprite>(0).Asset.State);e.Provider.AutoReleases=true;});
        [UnityTest] public IEnumerator CloseClearsTargetBeforeLeaseRelease()=>UniTask.ToCoroutine(async()=>{var e=await New();var binding=e.Binding(out var target);await e.Pump(binding.SetAsync(SpriteKey("a"),OperationContext.Unlimited()));e.Provider.AutoReleases=false;var close=binding.CloseAsync(Cleanup);Assert.IsNull(target.Value);Assert.AreEqual(UniTaskStatus.Pending,close.Status);e.Provider.AutoReleases=true;Assert.IsTrue((await e.Pump(close)).IsSuccess);});
        [UnityTest] public IEnumerator OwnerCloseCancelsLateBindingAndReclaims()=>UniTask.ToCoroutine(async()=>{var e=await New();e.Provider.AutoLoads=false;var binding=e.Binding(out var target);var set=binding.SetAsync(SpriteKey("a"),OperationContext.Unlimited());e.Step();var close=e.Owner.CloseAsync(Cleanup);Assert.IsNull(target.Value);e.Provider.AutoLoads=true;Assert.IsTrue((await e.Pump(close)).IsFullyDrained);Assert.IsFalse((await set).IsSuccess);Assert.IsNull(target.Value);});
        [UnityTest] public IEnumerator DeadlineDoesNotCommitOrAbandonLateAsset()=>UniTask.ToCoroutine(async()=>{var e=await New();var binding=e.Binding(out var target);Assert.AreEqual(ErrorKind.Timeout,(await binding.SetAsync(SpriteKey("a"),default)).Error.Kind);Assert.IsNull(target.Value);Assert.AreEqual(0,e.Provider.Fake.AssetStartCount);});
        [UnityTest] public IEnumerator DestroyedTargetSkipsWriteAndReleasesLateAsset()=>UniTask.ToCoroutine(async()=>{var e=await New();e.Provider.AutoLoads=false;var binding=e.Binding(out var target);var set=binding.SetAsync(SpriteKey("a"),OperationContext.Unlimited());e.Step();target.Alive=false;e.Provider.AutoLoads=true;Assert.IsFalse((await e.Pump(set)).IsSuccess);for(var i=0;i<4;i++){e.Step();await UniTask.Yield();}Assert.AreEqual(0,e.Assets.RetainedEntryCount);});
        [UnityTest] public IEnumerator PartialSetterFailureRetainsAssetUntilClearRetry()=>UniTask.ToCoroutine(async()=>{var e=await New();var binding=e.Binding(out var target);target.ThrowSet=true;Assert.IsFalse((await e.Pump(binding.SetAsync(SpriteKey("a"),OperationContext.Unlimited()))).IsSuccess);Assert.AreSame(e.A,target.Value);Assert.AreEqual(AssetLeaseState.Active,e.Provider.Fake.AssetAt<Sprite>(0).Asset.State);Assert.IsFalse((await binding.CloseAsync(Cleanup)).IsSuccess);target.ThrowSet=false;Assert.IsTrue((await e.Pump(binding.RetryCleanupAsync(Cleanup))).IsSuccess);Assert.AreEqual(0,e.Assets.RetainedEntryCount);});
        [UnityTest] public IEnumerator ClosingDoesNotEraseExternallyAssignedValue()=>UniTask.ToCoroutine(async()=>{var e=await New();var binding=e.Binding(out var target);await e.Pump(binding.SetAsync(SpriteKey("a"),OperationContext.Unlimited()));target.Value=e.B;await e.Pump(binding.CloseAsync(Cleanup));Assert.AreSame(e.B,target.Value);});
        [UnityTest] public IEnumerator ReentrantOwnerCloseDuringCommitCannotLeak()=>UniTask.ToCoroutine(async()=>{var e=await New();var binding=e.Binding(out var target);target.OnSet=()=>{target.OnSet=null;e.Owner.CloseAsync(Cleanup);};Assert.IsFalse((await e.Pump(binding.SetAsync(SpriteKey("a"),OperationContext.Unlimited()))).IsSuccess);Assert.IsNull(target.Value);Assert.IsTrue((await e.Pump(e.Owner.CloseAsync(Cleanup))).IsFullyDrained);});
        [UnityTest] public IEnumerator ImageAdapterUpdatesExistingComponentOnly()=>UniTask.ToCoroutine(async()=>{var e=await New();var go=new GameObject("authored",typeof(RectTransform),typeof(CanvasRenderer),typeof(Image));e.Objects.Add(go);var image=go.GetComponent<Image>();var count=go.GetComponents<Component>().Length;var binding=SpriteBindings.ForImage("image",image,e.Assets,e.Owner,Cleanup).Value;Assert.IsTrue((await e.Pump(binding.SetAsync(SpriteKey("a"),OperationContext.Unlimited()))).IsSuccess);Assert.AreSame(e.A,image.sprite);Assert.AreEqual(count,go.GetComponents<Component>().Length);});
        [UnityTest] public IEnumerator RendererAdapterUsesSameOwnershipContract()=>UniTask.ToCoroutine(async()=>{var e=await New();var go=new GameObject("renderer",typeof(SpriteRenderer));e.Objects.Add(go);var renderer=go.GetComponent<SpriteRenderer>();var binding=SpriteBindings.ForRenderer("renderer",renderer,e.Assets,e.Owner,Cleanup).Value;await e.Pump(binding.SetAsync(SpriteKey("a"),OperationContext.Unlimited()));Assert.AreSame(e.A,renderer.sprite);await e.Pump(binding.CloseAsync(Cleanup));Assert.IsNull(renderer.sprite);});
        [UnityTest] public IEnumerator OldChildRequestCannotWriteIntoNextPoolRental()=>UniTask.ToCoroutine(async()=>{var e=await New();var rent=await e.Rent();var image=rent.Value.GetComponentInChildren<Image>(true);var binding=SpriteBindings.ForChildImage("child",image,rent,e.Assets,Cleanup).Value;e.Provider.AutoLoads=false;var set=binding.SetAsync(SpriteKey("late"),OperationContext.Unlimited());e.Step();var returning=rent.ReturnAsync(Cleanup);Assert.AreEqual(0,e.Pool.IdleCount);e.Provider.AutoLoads=true;await e.Pump(returning);Assert.IsFalse((await set).IsSuccess);var next=await e.Rent();Assert.AreSame(image,next.Value.GetComponentInChildren<Image>(true));Assert.IsNull(image.sprite);Assert.IsFalse((await binding.SetAsync(SpriteKey("old"),OperationContext.Unlimited())).IsSuccess);});
        [UnityTest] public IEnumerator ForeignChildOwnerIsRejected()=>UniTask.ToCoroutine(async()=>{var e=await New();var a=await e.Rent();var b=await e.Rent();var foreign=b.Value.GetComponentInChildren<Image>(true);Assert.IsFalse(SpriteBindings.ForChildImage("wrong",foreign,a,e.Assets,Cleanup).IsSuccess);});
        [UnityTest] public IEnumerator ChildLeaseClearsBeforeObjectBecomesIdle()=>UniTask.ToCoroutine(async()=>{var e=await New();var rent=await e.Rent();var image=rent.Value.GetComponentInChildren<Image>(true);var binding=SpriteBindings.ForChildImage("child",image,rent,e.Assets,Cleanup).Value;await e.Pump(binding.SetAsync(SpriteKey("child"),OperationContext.Unlimited()));e.Provider.AutoReleases=false;var returning=rent.ReturnAsync(Cleanup);Assert.IsNull(image.sprite);Assert.AreEqual(0,e.Pool.IdleCount);Assert.AreEqual(AssetLeaseState.Active,e.Provider.Fake.AssetAt<GameObject>(0).Asset.State);e.Provider.AutoReleases=true;await e.Pump(returning);Assert.AreEqual(1,e.Pool.IdleCount);});
        [UnityTest] public IEnumerator ResourceSnapshotShowsKeyAndOwnerWithoutMutableLedger()=>UniTask.ToCoroutine(async()=>{var e=await New();var binding=e.Binding(out var target);await e.Pump(binding.SetAsync(SpriteKey("a"),OperationContext.Unlimited()));var snapshot=e.Assets.CaptureResources();Assert.AreEqual(1,snapshot.Entries.Count);Assert.AreEqual(SpriteKey("a"),snapshot.Entries[0].Key);Assert.AreEqual(1,snapshot.Entries[0].Interests);Assert.IsTrue(snapshot.Owners[0].HasLease);StringAssert.Contains("binding",snapshot.Owners[0].OwnerId);Assert.Throws<NotSupportedException>(()=>((IList<ResourceEntrySnapshot>)snapshot.Entries).Clear());await e.Pump(binding.CloseAsync(Cleanup));Assert.AreEqual(1,snapshot.Entries.Count);Assert.AreEqual(0,e.Assets.CaptureResources().Entries.Count);});
        [UnityTest] public IEnumerator PoolSnapshotSeparatesBucketOwnerAndRentalOwner()=>UniTask.ToCoroutine(async()=>{var e=await New();var rent=await e.Rent();var snapshot=e.Pool.CapturePoolResources();Assert.AreEqual(1,snapshot.Buckets[0].Active);Assert.AreEqual(e.Owner.Id,snapshot.Rents[0].OwnerId);Assert.AreEqual(rent.RentScope.Id,snapshot.Rents[0].RentScopeId);StringAssert.Contains("bucket",snapshot.Buckets[0].OwnerId);await rent.ReturnAsync(Cleanup);Assert.AreEqual(1,e.Pool.CapturePoolResources().Buckets[0].Idle);Assert.AreEqual(0,e.Pool.CapturePoolResources().Rents.Count);});
        [UnityTest] public IEnumerator ResourceDiagnosticsExposePendingAndReleaseFailure()=>UniTask.ToCoroutine(async()=>{var e=await New();e.Provider.AutoLoads=false;var binding=e.Binding(out var target);var set=binding.SetAsync(SpriteKey("a"),OperationContext.Unlimited());e.Step();Assert.IsTrue(e.Assets.CaptureResources().Entries[0].Loading);e.Provider.AutoLoads=true;await e.Pump(set);e.Provider.AutoReleases=false;var close=binding.CloseAsync(Cleanup);var asset=e.Provider.Fake.AssetAt<Sprite>(0).Asset;asset.ReleaseAttempt.Complete(Result<Unit>.Failure(new FrameworkError(ErrorKind.CleanupFailed,"injected")));Assert.IsFalse((await e.Pump(close)).IsSuccess);Assert.IsTrue(e.Assets.CaptureResources().Entries[0].ReleaseFailed);e.Provider.AutoReleases=true;await e.Pump(binding.RetryCleanupAsync(Cleanup));});
        [UnityTest] public IEnumerator PrefetchGateCancelsOnlyQueuedPrefetch()=>UniTask.ToCoroutine(async()=>{var e=await New();var n=0;var p=e.Scheduler.ScheduleFrame(()=>{n++;return Result<Unit>.Success(default);},ResourcePriority.Prefetch).Value;var normal=e.Scheduler.ScheduleFrame(()=>{n++;return Result<Unit>.Success(default);}).Value;using(e.Scheduler.SuppressPrefetch()){Assert.AreEqual(ErrorKind.Canceled,(await p.Completion).Error.Kind);Assert.IsFalse(e.Scheduler.ScheduleFrame(()=>Result<Unit>.Success(default),ResourcePriority.Prefetch).IsSuccess);e.Scheduler.Tick();Assert.IsTrue((await normal.Completion).IsSuccess);}Assert.AreEqual(1,n);Assert.IsFalse(e.Scheduler.IsPrefetchSuppressed);});
        [UnityTest] public IEnumerator NestedSuppressionGatesRestoreOnlyAfterLastDispose()=>UniTask.ToCoroutine(async()=>{var e=await New();var a=e.Scheduler.SuppressPrefetch();var b=e.Scheduler.SuppressPrefetch();a.Dispose();a.Dispose();Assert.IsTrue(e.Scheduler.IsPrefetchSuppressed);b.Dispose();Assert.IsFalse(e.Scheduler.IsPrefetchSuppressed);});
        [UnityTest] public IEnumerator PromotedQueuedWorkSurvivesPressure()=>UniTask.ToCoroutine(async()=>{var e=await New();var op=e.Scheduler.ScheduleFrame(()=>Result<Unit>.Success(default),ResourcePriority.Prefetch).Value;op.Promote(ResourcePriority.Critical);using(e.Scheduler.SuppressPrefetch()){e.Scheduler.Tick();Assert.IsTrue((await op.Completion).IsSuccess);}});
        [UnityTest] public IEnumerator PressurePreservesActiveAndDisplayedAssets()=>UniTask.ToCoroutine(async()=>{var e=await New();var active=await e.Rent();var idle=await e.Rent();var clone=idle.Value;await idle.ReturnAsync(Cleanup);var binding=e.Binding(out var target);await e.Pump(binding.SetAsync(SpriteKey("display"),OperationContext.Unlimited()));Assert.IsTrue((await e.Pump(e.Pressure.NotifyAsync(OperationContext.Unlimited()))).IsSuccess);Assert.IsTrue(clone==null);Assert.AreEqual(PoolRentState.Active,active.State);Assert.AreEqual(1,e.Pool.ActiveCount);Assert.AreSame(e.A,target.Value);Assert.AreEqual(AssetLeaseState.Active,e.Provider.Fake.AssetAt<GameObject>(0).Asset.State);});
        [UnityTest] public IEnumerator PressureEvictsIdleOnlyBucketAfterDestroyConfirmation()=>UniTask.ToCoroutine(async()=>{var e=await New();var idle=await e.Rent();var go=idle.Value;await idle.ReturnAsync(Cleanup);e.Provider.AutoReleases=false;var pressure=e.Pressure.NotifyAsync(OperationContext.Unlimited());Assert.IsTrue(e.Scheduler.IsPrefetchSuppressed);for(var i=0;i<5;i++){e.Step();await UniTask.Yield();}Assert.IsTrue(go==null);Assert.AreEqual(UniTaskStatus.Pending,pressure.Status);Assert.AreEqual(1,e.Pool.BucketCount);e.Provider.AutoReleases=true;Assert.IsTrue((await e.Pump(pressure)).IsSuccess);Assert.AreEqual(0,e.Pool.BucketCount);Assert.IsFalse(e.Scheduler.IsPrefetchSuppressed);});
        [UnityTest] public IEnumerator RepeatedMockNotificationsCoalesceOneActualPass()=>UniTask.ToCoroutine(async()=>{var e=await New();var rent=await e.Rent();await rent.ReturnAsync(Cleanup);e.Provider.AutoReleases=false;for(var i=0;i<100;i++)e.Source.Raise();Assert.AreEqual(1,e.Pressure.PassCount);Assert.AreEqual(99,e.Pressure.CoalescedCount);e.Provider.AutoReleases=true;await e.Pump(e.Pressure.NotifyAsync(OperationContext.Unlimited()));Assert.AreEqual(1,e.Pressure.PassCount);Assert.IsFalse(e.Pressure.IsRunning);});
        [UnityTest] public IEnumerator CallerCancellationDoesNotEndPressurePass()=>UniTask.ToCoroutine(async()=>{var e=await New();var rent=await e.Rent();await rent.ReturnAsync(Cleanup);e.Provider.AutoReleases=false;var cts=new CancellationTokenSource();var wait=e.Pressure.NotifyAsync(OperationContext.Unlimited(cts.Token));cts.Cancel();Assert.AreEqual(ErrorKind.Canceled,(await e.Pump(wait)).Error.Kind);Assert.IsTrue(e.Pressure.IsRunning);Assert.IsTrue(e.Scheduler.IsPrefetchSuppressed);e.Provider.AutoReleases=true;await e.Pump(e.Pressure.NotifyAsync(OperationContext.Unlimited()));cts.Dispose();});
        [UnityTest] public IEnumerator PressureDestroyBudgetSpansFrames()=>UniTask.ToCoroutine(async()=>{var e=await New(1);var rents=new List<IPoolRent<GameObject>>();var clones=new List<GameObject>();for(var i=0;i<3;i++){var r=await e.Rent();rents.Add(r);clones.Add(r.Value);}foreach(var r in rents)await r.ReturnAsync(Cleanup);var trim=e.Pressure.NotifyAsync(OperationContext.Unlimited());var dead=0;for(var frame=0;trim.Status==UniTaskStatus.Pending&&frame<30;frame++){await UniTask.NextFrame();var now=clones.FindAll(x=>x==null).Count;Assert.LessOrEqual(now-dead,1);dead=now;e.Step();}Assert.IsTrue((await e.Pump(trim)).IsSuccess);Assert.AreEqual(3,dead);});
        [UnityTest] public IEnumerator DestroyingIdleInstancesStillConsumeCapacity()=>UniTask.ToCoroutine(async()=>{var e=await New(1);var rents=new List<IPoolRent<GameObject>>();for(var i=0;i<8;i++)rents.Add(await e.Rent());foreach(var r in rents)await r.ReturnAsync(Cleanup);var trim=e.Pressure.NotifyAsync(OperationContext.Unlimited());Assert.AreEqual(8,e.Pool.CapturePoolResources().Buckets[0].Destroying);var failed=await e.Pump(e.Pool.Spawn(PrefabKey(),e.Owner).Value.WaitAsync(OperationContext.Unlimited()));Assert.AreEqual(ErrorKind.Unavailable,failed.Error.Kind);await e.Pump(trim);});
        [UnityTest] public IEnumerator PressureDoesNotAbortInFlightPrefabLoad()=>UniTask.ToCoroutine(async()=>{var e=await New();e.Provider.AutoLoads=false;var spawn=e.Pool.Spawn(PrefabKey(),e.Owner).Value.WaitAsync(OperationContext.Unlimited());e.Step();Assert.IsTrue((await e.Pressure.NotifyAsync(OperationContext.Unlimited())).IsSuccess);Assert.AreEqual(1,e.Scheduler.ActiveLoads);Assert.AreEqual(1,e.Pool.PendingCount);e.Provider.AutoLoads=true;Assert.IsTrue((await e.Pump(spawn)).IsSuccess);});
        [UnityTest] public IEnumerator FailedTrimRetainsBucketAndRestoresPrefetchGate()=>UniTask.ToCoroutine(async()=>{var e=await New();var rent=await e.Rent();await rent.ReturnAsync(Cleanup);e.Provider.AutoReleases=false;var pass=e.Pressure.NotifyAsync(OperationContext.Unlimited());var asset=e.Provider.Fake.AssetAt<GameObject>(0).Asset;for(var i=0;asset.ReleaseAttempt==null&&i<20;i++)await UniTask.Yield();asset.ReleaseAttempt.Complete(Result<Unit>.Failure(new FrameworkError(ErrorKind.CleanupFailed,"injected")));Assert.IsFalse((await e.Pump(pass)).IsSuccess);Assert.IsFalse(e.Scheduler.IsPrefetchSuppressed);Assert.AreEqual(1,e.Pool.BucketCount);Assert.Greater(e.Pool.CapturePoolResources().Buckets[0].FailedCleanup,0);e.Provider.AutoReleases=true;Assert.IsTrue((await e.Pump(e.Pool.EvictAsync(PrefabKey(),Cleanup))).IsSuccess);});
        [UnityTest] public IEnumerator ClosingContextUnsubscribesMockAndDrainsPass()=>UniTask.ToCoroutine(async()=>{var e=await New();var rent=await e.Rent();await rent.ReturnAsync(Cleanup);e.Provider.AutoReleases=false;e.Source.Raise();var close=e.Context.CloseAsync(OperationContext.Unlimited());Assert.AreEqual(0,e.Source.SubscriberCount);Assert.AreEqual(UniTaskStatus.Pending,close.Status);e.Provider.AutoReleases=true;Assert.IsTrue((await e.Pump(close)).IsSuccess);Assert.IsFalse(e.Scheduler.IsPrefetchSuppressed);Assert.IsFalse((await e.Pressure.NotifyAsync(OperationContext.Unlimited())).IsSuccess);});
        [UnityTest] public IEnumerator ZeroDeadlineDoesNotStartPressureWork()=>UniTask.ToCoroutine(async()=>{var e=await New();Assert.AreEqual(ErrorKind.Timeout,(await e.Pressure.NotifyAsync(default)).Error.Kind);Assert.AreEqual(0,e.Pressure.PassCount);});
        [UnityTest] public IEnumerator RepeatedBindingAndPressureCyclesReturnToBaseline()=>UniTask.ToCoroutine(async()=>{var e=await New();for(var i=0;i<30;i++){var binding=e.Binding(out var target);await e.Pump(binding.SetAsync(SpriteKey("a"+i),OperationContext.Unlimited()));await e.Pump(binding.CloseAsync(Cleanup));var rent=await e.Rent();await rent.ReturnAsync(Cleanup);await e.Pump(e.Pressure.NotifyAsync(OperationContext.Unlimited()));Assert.AreEqual(0,e.Assets.RetainedEntryCount);Assert.AreEqual(0,e.Pool.BucketCount);Assert.IsNull(target.Value);}Assert.AreEqual(0,e.Scheduler.ActiveLoads);});
        [UnityTest] public IEnumerator SuccessfulCleanupRetryClearsBindingFailureDiagnostics()=>UniTask.ToCoroutine(async()=>{var e=await New();var binding=e.Binding(out var target);target.ThrowSet=true;Assert.IsFalse((await e.Pump(binding.SetAsync(SpriteKey("a"),OperationContext.Unlimited()))).IsSuccess);Assert.Greater(binding.ReadDiagnostics().FailedCleanup,0);target.ThrowSet=false;Assert.IsTrue((await e.Pump(binding.RetryCleanupAsync(Cleanup))).IsSuccess);Assert.AreEqual(0,binding.ReadDiagnostics().FailedCleanup);});
        [UnityTest] public IEnumerator ForegroundJoinPromotesSharedPrefabBeforePressure()=>UniTask.ToCoroutine(async()=>{var e=await New();var warm=e.Pool.PrewarmAsync(PrefabKey(),1,e.Owner,OperationContext.Unlimited());var foreground=e.Pool.Spawn(PrefabKey(),e.Owner,ResourcePriority.Critical).Value.WaitAsync(OperationContext.Unlimited());await e.Pressure.NotifyAsync(OperationContext.Unlimited());Assert.IsTrue((await e.Pump(foreground)).IsSuccess,"Foreground demand must survive prefetch suppression");await e.Pump(warm);});
        [UnityTest] public IEnumerator DestroyedUnityImageCannotReceiveLateSprite()=>UniTask.ToCoroutine(async()=>{var e=await New();var go=new GameObject("destroy-image",typeof(RectTransform),typeof(CanvasRenderer),typeof(Image));e.Objects.Add(go);var binding=SpriteBindings.ForImage("destroy",go.GetComponent<Image>(),e.Assets,e.Owner,Cleanup).Value;e.Provider.AutoLoads=false;var set=binding.SetAsync(SpriteKey("a"),OperationContext.Unlimited());e.Step();Object.DestroyImmediate(go);e.Provider.AutoLoads=true;Assert.IsFalse((await e.Pump(set)).IsSuccess);for(var i=0;i<4;i++){e.Step();await UniTask.Yield();}Assert.AreEqual(0,e.Assets.RetainedEntryCount);});
        private sealed class PendingOperation:IProviderOperation<Unit>
        {internal readonly UniTaskCompletionSource<Result<Unit>> Source=new UniTaskCompletionSource<Result<Unit>>();public string Id=>"pending";public BackendState State=>Source.Task.Status==UniTaskStatus.Pending?BackendState.Running:BackendState.Succeeded;public UniTask<Result<Unit>> Completion=>Source.Task;}
        [UnityTest] public IEnumerator PressureNeverFreesRunningPrefetchSlotEarly()=>UniTask.ToCoroutine(async()=>{var e=await New();var backend=new PendingOperation();var job=e.Scheduler.Schedule(ResourceLane.Download,()=>Result<IProviderOperation<Unit>>.Success(backend),ResourcePriority.Prefetch).Value;e.Scheduler.Tick();using(e.Scheduler.SuppressPrefetch()){Assert.AreEqual(1,e.Scheduler.ActiveDownloads);Assert.AreEqual(ResourceWorkState.Running,job.SchedulingState);backend.Source.TrySetResult(Result<Unit>.Success(default));Assert.IsTrue((await job.Completion).IsSuccess);Assert.AreEqual(0,e.Scheduler.ActiveDownloads);}});
        [UnityTest] public IEnumerator CancellationContinuationCannotReplenishSuppressedPrefetch()=>UniTask.ToCoroutine(async()=>{var e=await New();var first=e.Scheduler.ScheduleFrame(()=>Result<Unit>.Success(default),ResourcePriority.Prefetch).Value;Result<IScheduledOperation<Unit>> attempted=default;async UniTask Replace(){await first.Completion;attempted=e.Scheduler.ScheduleFrame(()=>Result<Unit>.Success(default),ResourcePriority.Prefetch);}var replace=Replace().Preserve();using(e.Scheduler.SuppressPrefetch()){await replace;Assert.AreEqual(ErrorKind.Unavailable,attempted.Error.Kind);Assert.AreEqual(0,e.Scheduler.QueuedFrameUnits);}});
        private sealed class ThrowingTrim:IResourceTrimTarget {public UniTask<Result> TrimIdleAsync(int count,CleanupContext cleanup)=>throw new Exception("trim");}
        private sealed class TestContext:IModuleContext {public IServiceResolver Services=>null;public CancellationToken LifetimeCancellation=>default;public ICleanupRegistry Cleanup{get;}=new CleanupRegistry();}
        [UnityTest] public IEnumerator ThrowingTrimReturnsFailureAndRestoresGate()=>UniTask.ToCoroutine(async()=>{var e=await New();var source=new ManualMemoryPressureSource();var controller=new MemoryPressureController(source,e.Scheduler,new ThrowingTrim(),1,Cleanup,id:"fault-pressure");var context=new TestContext();await controller.InitializeAsync(context,OperationContext.Unlimited());Assert.IsFalse((await controller.NotifyAsync(OperationContext.Unlimited())).IsSuccess);Assert.IsFalse(e.Scheduler.IsPrefetchSuppressed);Assert.IsTrue((await context.Cleanup.CloseAsync(Cleanup)).IsFullyDrained);Assert.AreEqual(0,source.SubscriberCount);});
    }
